func type(_ value: String, _ x: CGFloat, _ y: CGFloat, _ size: CGFloat,
          _ face: String = regular, _ color: CGColor = ink,
          kern: CGFloat = 0, limit: CGFloat? = nil) {
    guard let font = NSFont(name: face, size: size) else { fatalError("Missing font: '"\\(face)\") }
    let string = NSAttributedString(string: value, attributes: [
        .font: font, .kern: kern,
        NSAttributedString.Key(kCTForegroundColorAttributeName as String): color
    ])
    let line = CTLineCreateWithAttributedString(string)
    let measure = CTLineGetTypographicBounds(line, nil, nil, nil)
    precondition(x + measure <= (limit ?? right) + 0.5, \"Text overflows: \\(value) [\\(measure)]\")
    precondition(y < 756 && y > 36, \"Baseline outside printable area\")
    context.textMatrix = .identity
    context.textPosition = CGPoint(x: x, y: paperHeight - y)
    CTLineDraw(line, context)
}

func marker(_ value: String, _ x: CGFloat, _ y: CGFloat) {
    type(value, x, y, 12, heavy, green, kern: 1.65)
}

func path(_ color: CGColor = lineInk, _ weight: CGFloat = 1,
          dash: [CGFloat] = [], _ draw: () -> Void) {
    context.saveGState()
    context.setStrokeColor(color)
    context.setLineWidth(weight)
    context.setLineCap(.round)
    context.setLineJoin(.round)
    context.setLineDash(phase: 0, lengths: dash)
    context.beginPath()
    draw()
    context.strokePath()
    context.restoreGState()
}

func point(_ x: CGFloat, _ y: CGFloat) -> CGPoint { CGPoint(x: x, y: paperHeight - y) }
func move(_ x: CGFloat, _ y: CGFloat) { context.move(to: point(x, y)) }
func to(_ x: CGFloat, _ y: CGFloat) { context.addLine(to: point(x, y)) }
func curve(_ x: CGFloat, _ y: CGFloat, _ a: CGFloat, _ b: CGFloat, _ c: CGFloat, _ d: CGFloat) {
    context.addCurve(to: point(x, y), control1: point(a, b), control2: point(c, d))
}

func rule(_ x: CGFloat, _ y: CGFloat, _ end: CGFloat, _ weight: CGFloat = 1,
          _ color: CGColor = lineInk, dash: [CGFloat] = []) {
    path(color, weight, dash: dash) { move(x, y); to(end, y) }
}

enum Symbol { case herbs, flowers, vegetables, envelope, sprout }

func symbol(_ kind: Symbol, _ x: CGFloat, _ y: CGFloat, _ size: CGFloat) {
    let s = size / 100
    func m(_ a: CGFloat, _ b: CGFloat) { move(x + a*s, y + b*s) }
    func l(_ a: CGFloat, _ b: CGFloat) { to(x + a*s, y + b*s) }
    func c(_ a: CGFloat, _ b: CGFloat, _ t: CGFloat, _ u: CGFloat, _ v: CGFloat, _ w: CGFloat) {
        curve(x + a*s, y + b*s, x + t*s, y + u*s, x + v*s, y + w*s)
    }
    func circle(_ a: CGFloat, _ b: CGFloat, _ r: CGFloat) {
        context.addEllipse(in: CGRect(x: x+(a-r)*s, y: paperHeight-y-(b+r)*s, width: 2*r*s, height: 2*r*s))
    }
    path(green, max(1.3, 2.35*s)) {
        switch kind {
        case .herbs:
            m(22, 89); c(72, 24, 45, 74, 63, 57)
            m(48, 64); c(22, 26, 23, 63, 16, 45); c(48, 64, 45, 32, 52, 46)
            m(53, 58); c(91, 50, 66, 42, 81, 45); c(53, 58, 82, 65, 67, 68)
            m(68, 37); c(69, 9, 63, 25, 64, 18); c(68, 37, 83, 17, 81, 26)
        case .flowers:
            circle(50, 39, 9)
            for i in 0..<8 {
                let angle = Double(i) * .pi / 4
                func p(_ radius: Double, _ delta: Double) -> (CGFloat, CGFloat) {
                    (50 + radius*cos(angle+delta), 39 + radius*sin(angle+delta))
                }
                let start = p(9, -0.26), end = p(9, 0.26)
                let a = p(30, -0.47), b = p(30, 0.47)
                m(start.0, start.1); c(end.0, end.1, a.0, a.1, b.0, b.1)
            }
            m(50, 64); c(50, 92, 47, 72, 48, 85)
            m(49, 85); c(27, 69, 39, 84, 30, 80); c(49, 85, 39, 70, 46, 72)
            m(50, 91); c(72, 76, 55, 80, 61, 76); c(50, 91, 69, 86, 61, 91)
        case .vegetables:
            m(75, 23); c(22, 70, 53, 22, 39, 32, 22, 70)
            c(14, 79, 18, 73, 16, 77); c(28, 82, 19, 81, 22, 82)
            c(60, 67, 40, 81, 51, 75); c(80, 25, 76, 54, 83, 39)
            c(89, 15, 82, 20, 85, 18)
            circle(39, 66, 4.3); circle(53, 54, 5); circle(65, 40, 5.6)
        case .envelope:
            m(10, 28); l(90, 28); l(90, 80); l(10, 80); l(10, 28)
            l(50, 58); l(90, 28)
            m(10, 80); l(37, 49)
            m(90, 80); l(63, 49)
            m(50, 8); l(50, 18)
            m(36, 12); l(41, 19)
            m(64, 12); l(59, 19)
        case .sprout:
            m(18, 84); c(82, 84, 38, 78, 62, 78)
            m(50, 80); c(53, 40, 50, 61, 51, 49)
            m(53, 49); c(78, 18, 53, 26, 62, 21); c(53, 49, 78, 36, 68, 46)
            m(51, 61); c(20, 34, 33, 60, 23, 51); c(51, 61, 36, 35, 48, 43)
        }
    }
}

func page(_ body: () -> Void) {
    context.beginPDFPage(nil)
    body()
    context.endPDFPage()
}

func top(_ label: String) {
    marker(label, left, 61)
    rule(left, 76, right, 1.25, green)
}

func footer(_ heading: String, _ detail: String) {
    rule(left, 662, right, 1.3, green)
    type(heading, left, 700, 24, bold, green)
    type(detail, left, 732, 19)
}

func signStep(_ number: String, _ heading: String, _ detail: [String], _ y: CGFloat) {
    type(number, left, y, 24, serif, green)
    type(heading, 91, y, 28, heavy)
    for (i, line) in detail.enumerated() { type(line, 91, y + 31 + CGFloat(i)*25, 20) }
}

func hostBlock(_ title: String, _ lines: [String], _ y: CGFloat) {
    rule(left, y - 24, right)
    type(title, left, y, 19, heavy, green)
    for (i, line) in lines.enumerated() { type(line, left, y + 24 + CGFloat(i)*19, 13.5) }
}

