func category(_ name: String, _ kind: Symbol, _ x: CGFloat, _ y: CGFloat) {
    symbol(kind, x, y - 17, 18)
    type(name.uppercased(), x + 23, y - 3, 10.5, heavy, green, kern: 1.35)
}

func label(_ x: CGFloat, _ y: CGFloat, _ seed: String?, _ name: String?, _ icon: Symbol?) {
    let maxX = x + 230
    type(\"COURTYARD SEED SWAP\", x, y + 23, 9, heavy, green, kern: 1.1, limit: maxX)
    if let seed, let name, let icon {
        type(seed, x, y + 58, 30, serif, limit: maxX)
        category(name, icon, x, y + 83)
    } else {
        type(\"Seed name and variety if known\", x, y + 47, 12, bold, limit: maxX)
        rule(x, y + 73, maxX)
        for (option, offset) in [(\"Herbs\", 0.0), (\"Flowers\", 66.0), (\"Vegetables\", 143.0)] {
            let box = x + offset
            path(ink, 1) { move(box, y + 89); to(box+9, y + 89); to(box+9, y + 98); to(box, y + 98); to(box, y + 89) }
            type(option, box + 13, y + 98, 11, bold, limit: maxX)
        }
    }
    type(\"Harvest year\", x, y + 127, 11.5, bold, limit: maxX)
    rule(x + 77, y + 129, maxX)
    type(\"Grown where\", x, y + 151, 11.5, bold, limit: maxX)
    rule(x + 77, y + 153, maxX)
    type(\"Notes\", x, y + 175, 11.5, bold, limit: maxX)
    rule(x + 39, y + 177, maxX)
}

func labelPage(starter: Bool) {
    page {
        top(\"COURTYARD SEED SWAP  /  PRINTABLE LABELS\")
        type(starter ? \"Starter packet labels\" : \"Blank packet labels\", left, 118, 38, serif)
        type(\"Fold and tear along the dashed lines. Tape labels to envelopes.\", left, 144, 13)
        let topEdge: CGFloat = 159
        let rowHeight: CGFloat = 196
        let middle: CGFloat = 306
        for row in 0...3 {
            rule(left, topEdge + CGFloat(row)*rowHeight, right, 0.85, lineInk, dash: [4, 3])
        }
        for x in [left, middle, right] {
            path(lineInk, 0.85, dash: [4, 3]) { move(x, topEdge); to(x, topEdge + 3*rowHeight) }
        }
        let seeds: [(String, String, Symbol)] = [(\"Basil\", \"Herbs\", .herbs), (\"Calendula\", \"Flowers\", .flowers), (\"Snap pea\", \"Vegetables\", .vegetables)]
        for row in 0..<3 {
            let (seed, name, icon) = seeds[row]
            for x in [left + 14, middle + 14] {
                label(x, topEdge + CGFloat(row)*rowHeight, starter ? seed : nil,
                      starter ? name : nil, starter ? icon : nil)
            }
        }
    }
}

